$hidden=static function() use($e,$csrfToken,$r,$id) { ?><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="intake_id" value="<?= $id ?>"><input type="hidden" name="revision" value="<?= (int)$r['revision'] ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(16)) ?>"><?php };
