    <section class="card"><div class="card-body"><h3>Incident Information</h3><dl><?php foreach (['Affected purok'=>$purok['purok_name']??null,'Recorded map risk'=>$purok['risk_classification']??null,'Incident date'=>$p['disaster_date'],'Disaster type'=>$p['disaster_type'],'Weather / conditions'=>$p['weather_name'],'Reported severity'=>$p['severity_level'],'Urgency'=>$p['is_urgent']===null?null:($p['is_urgent']?'Urgent':'Normal'),'Linked incident ID'=>$r['disaster_request_id'],'Latitude'=>$p['latitude']??null,'Longitude'=>$p['longitude']??null] as $label=>$v): ?><div><dt><?= $e($label) ?></dt><dd><?= $e($recorded($v)) ?></dd></div><?php endforeach; ?></dl><h4>Description</h4><p><?= nl2br($e($recorded($p['description']))) ?></p></div></section>
    <section class="card"><div class="card-body"><h3>Affected Population</h3><dl><?php foreach (['affected_households'=>'Households','affected_population'=>'Individuals','children'=>'Children','seniors'=>'Seniors','pwds'=>'PWDs','pregnant_women'=>'Pregnant women'] as $key=>$label): ?><div><dt><?= $e($label) ?></dt><dd><?= $e($recorded($p[$key])) ?></dd></div><?php endforeach; ?></dl><p class="field-hint">Counts were entered by the submitter, not inferred from household ratios. Vulnerable groups may overlap.</p></div></section>
</div>
<section class="card"><div class="card-body"><h3>Requested Resources</h3><div class="table-responsive"><table class="table"><thead><tr><th>Resource</th><th>Requested</th><th>Unit</th><th>Recorded allocated</th><th>Outstanding</th></tr></thead><tbody><?php foreach (Input::RESOURCES as $field=>$spec): ?><tr><td><?= $e($spec['label']) ?></td><td><?= $e($recorded($p[$field])) ?></td><td><?= $e($recorded($p[$field.'_unit'])) ?></td><td><?= $e($totals[$field]??'Not recorded') ?></td><td><?= $p[$field]===null?'Not recorded':max(0,(int)$p[$field]-($totals[$field]??0)) ?></td></tr><?php endforeach; ?></tbody></table></div><h4>Additional needs</h4><p><?= nl2br($e($recorded($p['additional_needs']))) ?></p><p class="field-hint">No quantitative demand is inferred from free text. Allocations below record stock released to this request, not confirmed resident distributions or claims.</p></div></section>
<section class="card" id="resource-ai-assessment"><div class="card-body"><h3>AI Priority Assessment</h3><p><strong>Experimental — not validated operational accuracy. Priority classification only; no quantity prediction.</strong></p><p>API assessment status: <strong><?= $e($r['ml_status']) ?></strong></p>
<?php if ($r['ml_result']): $m=$r['ml_result']['prediction']; ?><dl><div><dt>Model-predicted priority</dt><dd><?= $e($m['predicted_priority']) ?></dd></div><div><dt>Model-reported confidence (not accuracy)</dt><dd><?= $e($m['confidence']) ?>%</dd></div><div><dt>Algorithm / version</dt><dd><?= $e($m['algorithm']) ?><br><?= $e($m['model_version']??('CART-'.substr($m['model_sha256'],0,12))) ?></dd></div><div><dt>Model SHA-256</dt><dd><code><?= $e($m['model_sha256']) ?></code></dd></div><div><dt>Artifact save date (not verified training date)</dt><dd><?= $e($recorded($m['artifact_saved_at']??null)) ?></dd></div><div><dt>Verified training date</dt><dd>Not recorded</dd></div></dl><h4>Class probabilities</h4><dl><?php foreach ($m['probabilities'] as $label=>$prob): ?><div><dt><?= $e($label) ?></dt><dd><?= $e(round($prob*100,2)) ?>%</dd></div><?php endforeach; ?></dl><details><summary>Recorded features, decision path and limitations</summary><pre><?= $e(json_encode($r['ml_result']['features'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre><ul><?php foreach (array_merge($m['decision_path'],$m['feature_warnings']) as $text): ?><li><?= $e($text) ?></li><?php endforeach; ?></ul></details>
