<?php endif; ?>
<section class="card"><div class="card-body"><h3>Recorded Allocations</h3><div class="table-responsive"><table class="table"><thead><tr><th>Resource / request line ID</th><th>Actual stock item</th><th>Allocated quantity / unit</th><th>Authorizing officer / date</th></tr></thead><tbody><?php foreach ($allocations as $a): ?><tr><td><?= $e(Input::RESOURCES[$a['field']]['label']) ?> / #<?= (int)$a['resource_request_id'] ?></td><td>#<?= (int)$a['supply_id'] ?> <?= $e($a['supply_name']) ?></td><td><?= (int)$a['quantity'] ?> <?= $e($a['unit']) ?></td><td><?= $e($a['actor']) ?><br><?= $e($a['at']) ?></td></tr><?php endforeach; if (!$allocations): ?><tr><td colspan="4">No stock allocation has been recorded.</td></tr><?php endif; ?></tbody></table></div></div></section>
